package main

import (
	"context"
	"encoding/json"
	"log/slog"
	"time"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/api"
	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/internal/stream"
)

// Playback decision log (tv-playback-unblock D8): ONE INFO line per
// descriptor GET, emitted here in the composition root because this closure
// already holds mode/state/reason — api stays pure delegation and Describe
// stays pure. The line correlates with the request-log middleware's line for
// the same request. INV4: the line never carries a token value or a play URL
// — the reason is data, never credentials.

// The decision-log reason vocabulary beyond stream's descriptor honesty
// constants (those ride the stateReason pass-through verbatim), spelled
// exactly as the spec names them.
const (
	reasonPackaged   = "packaged"
	reasonUnpackaged = "unpackaged"
	reasonCooldown   = "cooldown"
	reasonFailed     = "failed"
)

// playbackDescriptor is the api.Deps.Playback closure body (D-7): pure
// delegation over the stream Service's Describe + a fresh media token, then
// the ONE decision-log line. The descriptor GET is the verb every playback
// actually hits (the SPA mounts the player from the descriptor's play_url —
// POST /play is only the failed-state retry affordance), so the closure also
// runs the SAME lazy repack-on-play decision the play verb runs
// (repack-descriptor-trigger): a legacy build enqueues exactly ONE repack
// through the ordinary EnqueuePack path while the GET still answers the
// current old build. enqueue is the shared EnqueuePack seam (the play verb's
// own); optInCodecs is the pack gate's opt-in knob. Otherwise read-only by
// contract: nothing here WRITES packaging state — the enqueue is the
// lane's normal trigger, the answer never changes for it, and the lane's
// per-item lease absorbs repeated GETs (never re-enqueued per request).
func playbackDescriptor(ctx context.Context, st *store.Store, mediaSvc *stream.Service, enqueue func(string) error, optInCodecs bool, itemID string) (api.Playback, error) {
	row, err := st.GetItem(ctx, itemID, access.System())
	if err != nil {
		return api.Playback{}, err // sql.ErrNoRows → 404 at the handler
	}
	var doc map[string]any
	if err := json.Unmarshal(row.Document, &doc); err != nil {
		return api.Playback{}, err
	}
	// Lazy repack trigger (repack-descriptor-trigger), BEFORE the answer is
	// composed: the same stale-build decision as the play verb, byte-for-byte
	// legacyRepackOnPlay semantics — complete state + a build nonce + a rule
	// version older than pack.MasterRuleVersion, PackGate pre-check, ONE
	// orchestrator line, enqueue into the dedup seam. The return values are
	// deliberately dropped: the GET never blocks on the decision and never
	// changes its answer — the descriptor below still serves the current old
	// build while the repack runs.
	legacyRepackOnPlay(enqueue, doc, itemID, optInCodecs)
	mode, state, playURL, sections, voiceovers, stateReason, codecs, codecsSrc, layout := mediaSvc.Describe(itemID, doc)
	token, _ := mediaSvc.Issue(itemID, time.Now()) // cookie-primary delivery
	logPlaybackDecision(itemID, mode, state,
		playbackDecisionReason(mode, state, stateReason, streamCooldowns(ctx, st)[itemID], time.Now()), codecsSrc)
	return api.Playback{
		Mode:        mode,
		State:       state,
		PlayURL:     playURL,
		StateReason: stateReason,
		Codecs:      codecs,
		Layout:      layout,
		Sections:    sections,
		Voiceovers:  voiceovers,
		Token:       token,
	}, nil
}

// playbackDecisionReason resolves the decision line's reason (D8): an hls
// answer logs `packaged` too — the log reads as a complete decision record,
// not a failure-only one. A direct answer names the first live gate: a
// pack-failed ledger row still gating the item (`cooldown` — retry later),
// else the failed run itself (`failed` — retry now), else the descriptor's
// honesty reason for the not-<video>-native floor (Describe's stateReason),
// else `unpackaged` — a plain floor awaiting or skipping its pack.
func playbackDecisionReason(mode, state, stateReason string, coolUntil, now time.Time) string {
	switch {
	case mode == stream.ModeHls:
		return reasonPackaged
	case coolUntil.After(now):
		return reasonCooldown
	case state == stream.StateFailed:
		return reasonFailed
	case stateReason != "":
		return stateReason
	default:
		return reasonUnpackaged
	}
}

// logPlaybackDecision emits the ONE decision line (D8's pinned shape,
// codecs_src added by pack-manifest-audio D7): item, mode, state, reason,
// codecs_src — the source naming which stream half answered the descriptor's
// codecs field (recorded | legacy | none). Never a token value, never a play
// URL, never the codec strings themselves (INV4) — the source name only.
func logPlaybackDecision(itemID, mode, state, reason, codecsSrc string) {
	slog.Info("playback: descriptor", "item", itemID, "mode", mode, "state", state, "reason", reason, "codecs_src", codecsSrc)
}
